    pub fn jsonParseFromValue(allocator: std.mem.Allocator, source: std.json.Value, options: std.json.ParseOptions) !@This() {
        return try openApiParseObjectFromValue(@This(), openApiFieldMetadata, allocator, source, options);
    }

    pub fn jsonStringify(self: @This(), jw: anytype) !void {
        try jw.beginObject();
        if (self.version) |value| {
            try jw.objectField("version");
            try jw.write(value);
        }
        if (self.storage_mode) |value| {
            try jw.objectField("storage_mode");
            try jw.write(value);
        }
        if (self.column_defaults) |value| {
            try jw.objectField("column_defaults");
            try jw.write(value);
        }
        if (self.generated_columns) |value| {
            try jw.objectField("generated_columns");
            try jw.write(value);
        }
        if (self.checks) |value| {
            try jw.objectField("checks");
            try jw.write(value);
        }
        if (self.unique_constraints) |value| {
            try jw.objectField("unique_constraints");
            try jw.write(value);
        }
        if (self.foreign_keys) |value| {
            try jw.objectField("foreign_keys");
            try jw.write(value);
        }
        if (self.relational_indexes) |value| {
            try jw.objectField("relational_indexes");
            try jw.write(value);
        }
        if (self.default_type) |value| {
            try jw.objectField("default_type");
            try jw.write(value);
        }
        if (self.enforce_types) |value| {
            try jw.objectField("enforce_types");
            try jw.write(value);
        }
        if (self.document_schemas) |value| {
            try jw.objectField("document_schemas");
            try jw.write(value);
        }
        switch (self.ttl) {
            .absent => {},
            .null_value => {
                try jw.objectField("ttl");
                try jw.write(@as(?u8, null));
            },
            .value => |value| {
                try jw.objectField("ttl");
                try jw.write(value);
            },
        }
        if (self.ttl_field) |value| {
            try jw.objectField("ttl_field");
            try jw.write(value);
        }
        if (self.ttl_duration) |value| {
            try jw.objectField("ttl_duration");
            try jw.write(value);
        }
        if (self.dynamic_templates) |value| {
            try jw.objectField("dynamic_templates");
            try jw.write(value);
        }
        try jw.endObject();
    }
};

/// Storage representation for the table. Omission selects "document". "relational" stores schema-bound typed rows and requires exactly one closed document schema with declared properties. It implies enforce_types; explicitly setting enforce_types to false is invalid. Existing JSON document write and read APIs remain available. This setting alone does not declare primary keys or unique constraints.
pub const TableStorageMode = enum {
    document,
    relational,

    pub fn jsonStringify(self: @This(), jw: anytype) !void {
        const s = switch (self) {
            .document => "document",
            .relational => "relational",
        };
        try jw.write(s);
    }

    pub fn jsonParse(_: std.mem.Allocator, source: anytype, _: std.json.ParseOptions) !@This() {
        const s = switch (try source.next()) {
            .string => |v| v,
            else => return error.UnexpectedToken,
        };
        const map = std.StaticStringMap(@This()).initComptime(.{
            .{ "document", .document },
            .{ "relational", .relational },
        });
        return map.get(s) orelse error.UnexpectedToken;
    }
};

/// Field mapping used by a dynamic template. Dynamic templates match one physical field at a time and therefore do not accept multifields; use a DocumentFieldMapping in a document property's `x-antfly-field` annotation when named subfields are required.
pub const TemplateFieldMapping = struct {
    type: ?FieldMappingType = null,
    /// Analyzer name (e.g., "standard", "keyword", "en", "html_analyzer"). Used for text fields to control tokenization and normalization.
    analyzer: ?[]const u8 = null,
    /// Whether to index the field. Omit to use the server default of true.
    index: ?bool = null,
    /// Whether to store the field value (default false)
    store: ?bool = null,
    /// Whether to include in the _all field for cross-field search
    include_in_all: ?bool = null,
    /// Whether this exact scalar field can be used in order_by. Supported sortable mapping types are keyword, numeric/number/integer, boolean/bool, datetime/date/timestamp, and link. Analyzed text, search_as_you_type, geo, embedding, blob, html, object, and array fields are not directly sortable; use an exact scalar subfield such as title.keyword for sorted string pagination. When true, Antfly derives the internal typed doc-value structures required for exact sorting; users should not configure doc_values directly.
    sortable: ?bool = null,
    /// Missing/null sort policy for this mapped field. The current production policy rejects missing or null native sort values so sorted cursors remain replayable JSON scalar tuples.
    missing_null_policy: ?[]const u8 = null,

    /// OpenAPI wire names and nullability consumed by compatible typed JSON parsers.
    pub const openApiFieldMetadata = .{
        .{ "type", "type", true },
        .{ "analyzer", "analyzer", true },
        .{ "index", "index", true },
        .{ "store", "store", true },
        .{ "include_in_all", "include_in_all", true },
        .{ "sortable", "sortable", true },
        .{ "missing_null_policy", "missing_null_policy", true },
    };

    pub fn jsonParse(allocator: std.mem.Allocator, source: anytype, options: std.json.ParseOptions) !@This() {
        return try openApiParseObject(@This(), openApiFieldMetadata, allocator, source, options);
    }

    pub fn jsonParseFromValue(allocator: std.mem.Allocator, source: std.json.Value, options: std.json.ParseOptions) !@This() {
        return try openApiParseObjectFromValue(@This(), openApiFieldMetadata, allocator, source, options);
    }

    pub fn jsonStringify(self: @This(), jw: anytype) !void {
        try jw.beginObject();
        if (self.type) |value| {
            try jw.objectField("type");
            try jw.write(value);
        }
        if (self.analyzer) |value| {
            try jw.objectField("analyzer");
            try jw.write(value);
        }
        if (self.index) |value| {
            try jw.objectField("index");
            try jw.write(value);
        }
        if (self.store) |value| {
            try jw.objectField("store");
            try jw.write(value);
        }
        if (self.include_in_all) |value| {
            try jw.objectField("include_in_all");
            try jw.write(value);
        }
        if (self.sortable) |value| {
            try jw.objectField("sortable");
            try jw.write(value);
        }
        if (self.missing_null_policy) |value| {
            try jw.objectField("missing_null_policy");
            try jw.write(value);
        }
        try jw.endObject();
    }
};

/// Automatic document-expiration policy for a table.
pub const TtlConfig = struct {
    /// Expiration duration using Antfly's integer-component duration format. Supported units are `ns`, `us`, `ms`, `s`, `m`, `h`, and `d`; examples include `90m`, `1h30m`, and `7d`.
    duration: []const u8,
    /// Timestamp field used as the expiration reference.
    field: ?[]const u8 = null,

    /// OpenAPI wire names and nullability consumed by compatible typed JSON parsers.
    pub const openApiFieldMetadata = .{
        .{ "duration", "duration", false },
        .{ "field", "field", true },
    };

    pub fn jsonParse(allocator: std.mem.Allocator, source: anytype, options: std.json.ParseOptions) !@This() {
        return try openApiParseObject(@This(), openApiFieldMetadata, allocator, source, options);
    }

    pub fn jsonParseFromValue(allocator: std.mem.Allocator, source: std.json.Value, options: std.json.ParseOptions) !@This() {
        return try openApiParseObjectFromValue(@This(), openApiFieldMetadata, allocator, source, options);
    }

    pub fn jsonStringify(self: @This(), jw: anytype) !void {
        try jw.beginObject();
        try jw.objectField("duration");
        try jw.write(self.duration);
        if (self.field) |value| {
            try jw.objectField("field");
            try jw.write(value);
        }
        try jw.endObject();
    }
};

/// Presence-aware representation of an optional OpenAPI property that also permits JSON null.
pub fn OpenApiOptionalNullable(comptime T: type) type {
    return union(enum) {
        absent,
        null_value,
        value: T,

        pub fn fromNullable(value: ?T) @This() {
            return if (value) |item| .{ .value = item } else .null_value;
        }

        pub fn isPresent(self: @This()) bool {
            return self != .absent;
        }

        pub fn valueOrNull(self: @This()) ?T {
            return switch (self) {
                .absent, .null_value => null,
                .value => |item| item,
            };
        }

        pub fn jsonParse(allocator: std.mem.Allocator, source: anytype, options: std.json.ParseOptions) !@This() {
            if (try source.peekNextTokenType() == .null) {
                _ = try source.next();
                return .null_value;
            }
            return .{ .value = try std.json.innerParse(T, allocator, source, options) };
        }

        pub fn jsonParseFromValue(allocator: std.mem.Allocator, source: std.json.Value, options: std.json.ParseOptions) !@This() {
            if (source == .null) return .null_value;
            return .{ .value = try std.json.parseFromValueLeaky(T, allocator, source, options) };
        }

        pub fn jsonStringify(self: @This(), jw: anytype) !void {
            switch (self) {
                .absent => return error.OptionalNullablePropertyAbsent,
                .null_value => try jw.write(@as(?u8, null)),
                .value => |value| try jw.write(value),
            }
        }
    };
}

/// Parse an OpenAPI object without materializing a second JSON tree while
/// rejecting explicit null for optional properties whose schemas are non-nullable.
fn openApiParseObject(
    comptime T: type,
    comptime openapi_fields: anytype,
    allocator: std.mem.Allocator,
    source: anytype,
    options: std.json.ParseOptions,
) !T {
    @setEvalBranchQuota(100_000);
    const struct_info = @typeInfo(T).@"struct";
    if (struct_info.is_tuple) @compileError("OpenAPI object parser does not accept tuples");
    if (openapi_fields.len != struct_info.fields.len) @compileError("OpenAPI object field descriptors must match the generated struct");
    if (.object_begin != try source.next()) return error.UnexpectedToken;

    var result: T = undefined;
    var fields_seen = [_]bool{false} ** struct_info.fields.len;
    while (true) {
        var name_token: ?std.json.Token = try source.nextAllocMax(allocator, .alloc_if_needed, options.max_value_len.?);
        const field_name = switch (name_token.?) {
            inline .string, .allocated_string => |slice| slice,
            .object_end => break,
            else => return error.UnexpectedToken,
        };

        inline for (struct_info.fields, openapi_fields, 0..) |field, openapi_field, i| {
            if (field.is_comptime) @compileError("comptime fields are not supported: " ++ @typeName(T) ++ "." ++ field.name);
            if (comptime !std.mem.eql(u8, field.name, openapi_field[1])) @compileError("OpenAPI object field descriptor order does not match the generated struct");
            if (std.mem.eql(u8, openapi_field[0], field_name)) {
                openApiFreeAllocatedToken(allocator, name_token.?);
                name_token = null;
                if (openapi_field[2] and try source.peekNextTokenType() == .null) return error.UnexpectedToken;
                if (fields_seen[i]) {
                    switch (options.duplicate_field_behavior) {
                        .use_first => {
                            _ = try std.json.innerParse(field.type, allocator, source, options);
                            break;
                        },
                        .@"error" => return error.DuplicateField,
                        .use_last => {},
                    }
                }
                @field(result, field.name) = try std.json.innerParse(field.type, allocator, source, options);
                fields_seen[i] = true;
                break;
            }
        } else {
            openApiFreeAllocatedToken(allocator, name_token.?);
            if (options.ignore_unknown_fields) try source.skipValue() else return error.UnknownField;
        }
    }
    try openApiFillDefaultStructValues(T, openapi_fields, &result, &fields_seen);
    return result;
}

fn openApiParseObjectFromValue(
    comptime T: type,
    comptime openapi_fields: anytype,
    allocator: std.mem.Allocator,
    source: std.json.Value,
    options: std.json.ParseOptions,
) !T {
    @setEvalBranchQuota(100_000);
    const struct_info = @typeInfo(T).@"struct";
    if (struct_info.is_tuple) @compileError("OpenAPI object parser does not accept tuples");
    if (openapi_fields.len != struct_info.fields.len) @compileError("OpenAPI object field descriptors must match the generated struct");
    if (source != .object) return error.UnexpectedToken;
    var result: T = undefined;
    var fields_seen = [_]bool{false} ** struct_info.fields.len;
    var it = source.object.iterator();
    while (it.next()) |entry| {
        const field_name = entry.key_ptr.*;
        inline for (struct_info.fields, openapi_fields, 0..) |field, openapi_field, i| {
            if (field.is_comptime) @compileError("comptime fields are not supported: " ++ @typeName(T) ++ "." ++ field.name);
            if (comptime !std.mem.eql(u8, field.name, openapi_field[1])) @compileError("OpenAPI object field descriptor order does not match the generated struct");
            if (std.mem.eql(u8, openapi_field[0], field_name)) {
                if (openapi_field[2] and entry.value_ptr.* == .null) return error.UnexpectedToken;
                @field(result, field.name) = try std.json.innerParseFromValue(field.type, allocator, entry.value_ptr.*, options);
                fields_seen[i] = true;
                break;
            }
        } else if (!options.ignore_unknown_fields) return error.UnknownField;
    }
    try openApiFillDefaultStructValues(T, openapi_fields, &result, &fields_seen);
    return result;
}

fn openApiFillDefaultStructValues(comptime T: type, comptime openapi_fields: anytype, result: *T, fields_seen: *[@typeInfo(T).@"struct".fields.len]bool) !void {
    @setEvalBranchQuota(100_000);
    inline for (@typeInfo(T).@"struct".fields, openapi_fields, 0..) |field, openapi_field, i| {
        if (comptime !std.mem.eql(u8, field.name, openapi_field[1])) @compileError("OpenAPI object field descriptor order does not match the generated struct");
        if (!fields_seen[i]) {
            if (field.defaultValue()) |default| @field(result, field.name) = default else return error.MissingField;
        }
    }
}

fn openApiFreeAllocatedToken(allocator: std.mem.Allocator, token: std.json.Token) void {
    switch (token) {
        .allocated_number, .allocated_string => |slice| allocator.free(slice),
        else => {},
    }
}
